/*
 * The three.js bundle as Jocly loads it, outside the browser.
 *
 *   node tests/three/three-bundle.test.js
 *
 * third-party/three.js and third-party/three-addons.js are GENERATED by
 * tools/three/build-three.js (npm run three) since r186 stopped shipping a
 * real CommonJS build. This checks what the generation must keep true:
 *
 *  - three.js, evaluated the way BrowserScriptLoader.import does it -
 *    `(function(exports){ <source> ;return exports; })({})` - fills that
 *    exports object with the THREE namespace;
 *  - three-addons.js, evaluated next as a plain script, hangs GLTFLoader,
 *    BufferGeometryUtils, FontLoader, Font and TextGeometry on THREE, and
 *    they are of the same revision as the core (no copy lagging behind);
 *  - TextGeometry is driven by `depth`, as every Jocly view now passes it:
 *    r186 no longer reads `height`, and silently extrudes 50 units instead.
 */

const fs = require("fs");
const path = require("path");
const vm = require("vm");

const H = require("../fairy/harness.js");
const t = H.runner();

const ROOT = path.join(__dirname, "..", "..");
const core = fs.readFileSync(path.join(ROOT, "third-party", "three.js"), "utf8");
const addons = fs.readFileSync(path.join(ROOT, "third-party", "three-addons.js"), "utf8");

const sandbox = { console, self: {}, performance, setTimeout, clearTimeout };
sandbox.window = sandbox;
vm.createContext(sandbox);
const THREE = vm.runInContext("(function(exports){\n" + core + "\n;return exports;\n})({})", sandbox);
sandbox.THREE = THREE;
vm.runInContext(addons, sandbox);

t.check("the core fills the exports object", typeof THREE.WebGLRenderer, "function");
t.check("revision", THREE.REVISION, require(path.join(ROOT, "package.json")).devDependencies.three.split(".")[1]);
for(const name of ["GLTFLoader", "FontLoader", "Font", "TextGeometry"])
	t.check(name + " is on THREE", typeof THREE[name], "function");
t.check("BufferGeometryUtils.mergeVertices is on THREE",
	typeof (THREE.BufferGeometryUtils || {}).mergeVertices, "function");
t.check("the addons extend THIS core, not a copy of their own",
	new THREE.TextGeometry("", { font: { generateShapes: () => [] }, depth: 1 }) instanceof THREE.BufferGeometry, true);

// the banner the generator writes, so a hand edit or a stale file shows
t.check("three.js says it is generated", /regenerated by tools\/three\/build-three\.js/.test(core.slice(0, 300)), true);

const fontFile = path.join(ROOT, "src", "games", "mana", "res", "xd-view", "fonts", "helvetiker_regular.typeface.json");
const font = new THREE.FontLoader().parse(JSON.parse(fs.readFileSync(fontFile, "utf8")));
function thickness(params) {
	const g = new THREE.TextGeometry("12", Object.assign({ size: 0.2, curveSegments: 6, font }, params));
	g.computeBoundingBox();
	return +(g.boundingBox.max.z - g.boundingBox.min.z).toFixed(4);
}
t.check("depth: 0.05 gives a 0.05 thick text", thickness({ depth: 0.05 }), 0.05);
t.check("height is ignored by r186 (hence depth everywhere)", thickness({ height: 0.05 }) > 1, true);

// and no view is left passing height to it
const stale = [];
(function walk(dir) {
	for(const e of fs.readdirSync(dir, { withFileTypes: true })) {
		const full = path.join(dir, e.name);
		if(e.isDirectory()) walk(full);
		else if(/\.js$/.test(e.name)) {
			const lines = fs.readFileSync(full, "utf8").split("\n");
			lines.forEach((l, i) => {
				if(/new THREE\.TextGeometry\(/.test(l) &&
					lines.slice(i, i + 8).some((x) => /\bheight\s*:/.test(x)))
					stale.push(path.relative(ROOT, full) + ":" + (i + 1));
			});
		}
	}
})(path.join(ROOT, "src"));
t.check("no TextGeometry call passes height", stale, []);

t.done("three bundle");
